      "commonQuestions": "자주 묻는 질문 (FAQ)",
      "faq1A": "아닙니다. 메시지나 전화 문의는 단순 상담이며, 실제 예약 및 판매 여부는 판매자와 직접 협의하셔야 합니다.",
      "faq1Q": "판매자에게 문의하면 차량이 예약되나요?",
